 (n - 3)))\n\nprint(f\"G2 (direct formula): {G2_direct}\")\n\n# Let me also try using the simpler version\n# G2 = ((n+1)*g2 + 6) * (n-1) / ((n-2)*(n-3))\n# where g2 uses sample std (ddof=1)\n\nprint(\"\\n--- With sample std (ddof=1) for standardized values ---\")\n# Let's use the exact formula from scipy.stats\n# The formula scipy uses is:\n#   kurtosis = (n-1)/((n-2)(n-3)) * ((n+1)*g2 + 6)\n# where g2 is computed with ddof=1\n\n# Compute g2 using sample std\nstd_ddof1 = math.sqrt(sum((x - mean) ** 2 for x in data) / (n - 1))\ng2_ddof1 = sum(((x - mean) / std_ddof1) ** 4 for x in data) / n - 3\n\nprint(f\"g2 (with ddof=1 std): {g2_ddof1}\")\n\n# This formula: G2 = (n-1)/(n-2)(n-3) * ((n+1)*g2 + 6)\nG2_scipy = (n - 1) / ((n - 2) * (n - 3)) * ((n + 1) * g2_ddof1 + 6)\nprint(f\"G2 (scipy formula): {G2_scipy}\")\n\n# This should match what scipy returns with fisher=True, bias=False\nprint(f\"\\nFinal value (rounded to 3 decimal places): {round(G2_scipy, 3)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
