d): {G2_scipy}\")\n\n# Let me also check using the formula that should give approx 0 for normal\n# The exact unbiased formula per SAS/SPSS is:\n# G2 = [(n-1)/((n-2)(n-3))] * [(n+1)g2 + 6]\n\n# Let's also verify with formula from literature\n# From http://www.jerrydallal.com/LHSP/slope.htm\n# G2 = (n+1)*n*g2 / ((n-1)*(n-2)*(n-3)) - 3*(n-1)^2 / ((n-2)*(n-3))\n\nG2_alt = (n + 1) * n * g2 / ((n - 1) * (n - 2) * (n - 3)) - 3 * (n - 1) ** 2 / ((n - 2) * (n - 3))\nprint(f\"G2 (alternative formula): {G2_alt}\")\n\n# I'll also check online references - the Joanes and Gill (1998) paper\n# compares the formulas. Their \"G2\" formula is:\n# G2 = (n-1)/((n-2)(n-3)) * ((n+1)g2 + 6)\n# which matches scipy formula above\n\n# For the original calculation with the dollar data\nprint(\"\\n--- Original dollar data ---\")\ndata = [8932, 11600, 16492, 21438, 25511, 26945, 26942, 26182, 26034, 25661]\nn = len(data)\nmean = sum(data) / n\nstd = math.sqrt(sum((x - mean) ** 2 for x in data) / (n - 1))\ng2 = sum(((x - mean) / std) ** 4 for x in data) / n - 3\nG2 = (n - 1) / ((n - 2) * (n - 3)) * ((n + 1) * g2 + 6)\nprint(f\"Unbiased sample Fisher excess Kurtosis: {G2}\")\nprint(f\"Rounded to 3 decimals: {round(G2, 3)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
