n# G2 = (n-1)/((n-2)(n-3)) * ((n+1)*g2 + 6)\n# where g2 = (m4/m2^2) - 3 using sample moments\n\n# Using Python's scipy formula verification:\n# In scipy.stats, the excess kurtosis is computed as:\n#   kurtosis = moment / (std ** 4) - 3\n# where moment = sum((x - mean)**4) / len(x)\n# and std is computed with ddof=1 (sample std)\n\n# The bias correction (fisher=False, bias=False) applies:\n#   G2 = ((n+1)*kurtosis + 6) * (n-1) / ((n-2)*(n-3))\n\ndata = [8932, 11600, 16492, 21438, 25511, 26945, 26942, 26182, 26034, 25661]\nn = len(data)\nmean = sum(data) / n\nstd = math.sqrt(sum((x - mean) ** 2 for x in data) / (n - 1))\n\n# This is what scipy computes for fisher=True, bias=False:\nmoment4 = sum((x - mean) ** 4 for x in data) / n\nkurtosis = moment4 / (std ** 4) - 3\n\nG2 = ((n + 1) * kurtosis + 6) * (n - 1) / ((n - 2) * (n - 3))\n\nprint(f\"\\nData: {data}\")\nprint(f\"Kurtosis (biased): {kurtosis}\")\nprint(f\"Unbiased sample Fisher excess Kurtosis: {G2}\")\nprint(f\"Rounded: {round(G2, 3)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
